"""Original shared SL/HL methodology practice for first assessment 2027."""
from common import *
import textwrap

GUIDE='https://ibo.org/globalassets/new-structure/university-admission/pdfs/subject-guides/psychology-first-assessment-2027-guide-sbs.pdf'
CASES=[]

def flow(title, labels):
    body=''.join(text(180,22+i*21,s,16,'middle') for i,s in enumerate(textwrap.wrap(title,39)))
    positions=[(16,60),(200,60),(200,210),(16,210)]
    for i,label in enumerate(labels):
        x,y=positions[i]
        body+=rect(x,y,144,100)
        for j,s in enumerate(textwrap.wrap(label,17)):
            body+=text(x+72,y+29+j*21,s,15,'middle')
    body+=line(161,110,197,110)+'<polygon points="197,110 190,105 190,115" fill="#412b2b"/>'
    body+=line(272,161,272,207)+'<polygon points="272,207 267,200 277,200" fill="#412b2b"/>'
    body+=line(199,260,163,260)+'<polygon points="163,260 170,255 170,265" fill="#412b2b"/>'
    body+=text(180,340,'Constructed research — procedure only.',12,'middle')
    return svg(body,360,355,'Process diagram for a fictitious class practical')

CASES.append(dict(title='Follow-up questions about everyday routines',context='health-wellbeing',concept='bias',codes=['RES.01','RES.06','RES.07','RES.08'],
case='A teacher-approved fictitious class practical concerns everyday routines that adults use to take breaks while studying. Eight volunteers aged 17 or over consent to individual eight-minute interviews. A student uses the same opening questions for everyone, but may ask neutral follow-up questions. The interviewer is also the participants’ study-group coordinator. Interviews are private; identifying details are removed from the transcripts. No questions concern diagnoses or distressing personal experiences.',
nodes=['Volunteer invitation','Private consent','Common questions plus follow-ups','De-identified transcripts'],
k=('Explain two features that make this a semi-structured interview rather than a structured interview.',[
'An interview obtains an account through interaction between an interviewer and a participant. Here the common opening questions create a consistent starting point, so each participant has an opportunity to discuss the same broad issue of study breaks. This consistency does not make the procedure fully structured.',
'The permission to ask additional neutral questions makes it semi-structured. For example, an interviewer could ask what a participant means by “a proper break”, then explore that meaning without offering an answer. A structured interview fixes the questions and usually their order, giving less freedom to follow an unanticipated account.']),
a=('Using the concept of bias, explain how the interviewer’s coordinator role could affect these accounts.',[
'Participants may regard the coordinator as someone who judges commitment to the study group. They could present socially approved routines or omit breaks they expect the coordinator to dislike. The resulting account would reflect the relationship and expected judgement as well as the routine itself; consent alone does not remove this pressure.',
'The coordinator might also probe approvingly when an answer matches their own preferred habits. This would make the depth of the resulting transcripts uneven. A separate interviewer, neutral probes and a reflexive record of assumptions would reduce these pathways. They would not guarantee that every answer becomes an unbiased record of behaviour.']),
c=('Compare and contrast using these semi-structured interviews with using an anonymous open-ended questionnaire for the same aim.',[
'Both methods can collect participants’ descriptions in their own words, so both can reveal meanings that a fixed-choice habit checklist would miss. Neither automatically establishes what participants actually do during an unobserved study session: each relies on self-report.',
'The interview permits clarification of an ambiguous phrase such as “often”. This can deepen the account, but the coordinator’s presence can influence what is said. An anonymous questionnaire removes that immediate relationship and may improve candour, while offering no live opportunity to check what a short answer means.',
'Anonymity also changes the practical options. The questionnaire can be completed independently at a convenient time, but a researcher cannot follow up with a particular respondent after identities have been irreversibly removed. The choice should therefore follow whether depth of meaning or reduced interpersonal pressure is more important to the aim.']),
d=('Design one feasible improvement that reduces interviewer influence while retaining the depth of the interview method.',[
'Use a trained interviewer who has no coordinating or assessment role with these volunteers. Explain that the coordinator will receive only de-identified material and cannot connect a particular account to a group member. Obtain consent again for the revised arrangement and retain the right to stop without a penalty.',
'Retain the common opening questions but agree neutral probes, such as asking a participant to describe an example in their own terms. Avoid praising a particular routine. Pilot the wording with a consenting adult outside the main sample to check that questions do not imply a preferred answer.',
'Record the interview only with explicit permission, then remove names and keep the recording securely until the agreed deletion point. The interviewer should note assumptions and unexpected reactions in a reflexive log. This makes the influence open to scrutiny; it does not justify describing the revised interviews as entirely objective.'])))

CASES.append(dict(title='The staffroom recruitment boundary',context='health-wellbeing',concept='perspective',codes=['RES.02','RES.02','RES.07','RES.08'],
case='In this fictitious practical, a class interviews adults about convenient ways to build movement breaks into a working day. The researcher approaches the first six consenting staff members present in a school staffroom at lunchtime. The interviews use a fixed question list. Staff who work at other sites or have lunchtime duties cannot be approached there. The questions concern practical preferences, not illness, and participation has no link to employment assessment.',
nodes=['One staffroom at lunch','Available consenting staff','Fixed interview questions','Preferences reported'],
k=('Explain why this is opportunity sampling and distinguish it from random sampling.',[
'The researcher selects people who are conveniently available in one place at one time. Being a member of staff is not sufficient for selection: a person must also happen to be in this staffroom at lunchtime and agree to take part. Those accessibility conditions make the sample an opportunity sample.',
'Random sampling instead requires a defined sampling frame and a chance-based selection procedure. Approaching the first six people does not give everyone on the staff list a known selection opportunity, even if the researcher feels that the staffroom contains a varied group. Random selection would also remain distinct from whether selected staff consent.']),
a=('Using perspective, explain why the recruitment location matters to the account of convenient movement breaks.',[
'Convenience is experienced from a person’s working conditions. Staff who can spend lunchtime in the staffroom may have more control over break timing than staff supervising pupils or moving between sites. Their suggestions could therefore reflect a particular working perspective rather than a universally convenient routine.',
'The issue is not that those six accounts are invalid or insincere. They can accurately represent their own circumstances while leaving other circumstances unexplored. The researcher should describe the recruitment boundary and seek accounts from differently situated staff before treating the suggestions as suitable across the school.']),
c=('Compare and contrast this opportunity sample with a stratified random sample of staff from different work roles.',[
'Both approaches select a subset of a wider staff population and both require voluntary, informed consent. Neither can compel a chosen adult to be interviewed. The same fixed interview list could be used with either sample, so differences in sampling need not be confused with differences in interview wording.',
'The opportunity approach is quick and workable for a class exercise, but staffroom availability shapes inclusion. A stratified random approach first groups a complete staff list by relevant work role, then makes chance-based selections within those groups. This provides a planned route to include roles absent from the lunchtime setting.',
'A stratified procedure takes more preparation and depends on an adequate staff list. Refusals and different response rates can still undermine the intended balance. It improves the basis for population coverage without guaranteeing that a small interview sample captures every relevant experience.']),
d=('Design a recruitment procedure that includes staff with lunchtime duties while respecting voluntary participation.',[
'Define the target population as staff at all school sites, then ask an authorised school contact to distribute neutral invitations through channels accessible to each work role. Offer private interview appointments before or after duties, without requiring supervisors to nominate particular employees.',
'If the aim is planned coverage, use a staff list with appropriate permission to select within role groups and invite selected people individually. Record invitations and refusals without recording reasons that participants do not wish to give. Use a pre-agreed replacement rule within the same role rather than quietly returning to whoever is easiest to reach.',
'Explain that the school receives de-identified findings and that declining has no employment consequence. Report the final recruitment pattern and the roles still missing. The procedure addresses the original time-and-place exclusion; it does not entitle the researcher to claim that every staff perspective is represented.'])))

CASES.append(dict(title='An interviewer who shares the routine',context='health-wellbeing',concept='responsibility',codes=['RES.06','RES.04','RES.07','RES.08'],
case='A fictitious class interview explores how adults choose a regular bedtime routine. The student interviewer strongly favours leaving devices outside the bedroom. Four consenting adults aged 18 or over describe their own preferences in private semi-structured interviews. Before analysing the transcripts, the interviewer notices that the follow-up questions were longer when a participant also preferred leaving a device outside. No actual study or clinical assessment is proposed here.',
nodes=['Interviewer preference','Private interviews','Uneven follow-up questions','Reflexive review'],
k=('Explain the role of reflexivity in this qualitative research situation.',[
'Reflexivity means examining how the researcher’s position, expectations and choices may influence the research process. In this case it includes recognising that a personal preference about devices shaped which answers received longer follow-up questions. This is more specific than simply saying that the interviewer has an opinion.',
'A reflexive record could document the preference, identify the points at which questioning became uneven and explain how later interviewing or interpretation was changed. It does not erase the uneven transcripts already produced. Its value is to make the researcher’s contribution visible and open to critical assessment.']),
a=('Using responsibility, explain how the interviewer should respond to discovering the unequal probing.',[
'The interviewer has a responsibility to represent participants fairly rather than treat agreement as more worth exploring. Longer probes can give agreeing participants more opportunities to explain themselves, making those views appear richer in the final account. The discovery should therefore be documented rather than concealed as an inconvenient detail.',
'The researcher can review the recordings, describe the imbalance and consider whether a voluntary, neutrally worded follow-up is justified. Participants should not be pressed to change their views. Reporting the limitation and separating personal recommendations from what participants actually said protects both the integrity of the account and participants’ control over their contributions.']),
c=('Compare and contrast a reflexive log with using a second researcher to review the interview process.',[
'Both approaches can expose decisions that a single researcher might otherwise treat as neutral. A reflexive log records the interviewer’s own assumptions and reactions during the process; an independent reviewer can examine whether the actual questions appear to favour a particular answer.',
'The log provides access to the interviewer’s reasoning, including choices that may not be visible in a transcript. Its weakness is that the same person may overlook their own influence. A second reviewer adds another perspective, but may share the original preference or lack the contextual knowledge needed to understand a particular probe.',
'Neither procedure proves that the eventual interpretation is uniquely correct. They can work together: the reviewer considers the questioning alongside the log, and the report explains disagreements and any changes made. Their contribution is greater transparency and critical scrutiny, rather than automatic removal of subjectivity.']),
d=('Design a revised interview procedure that gives different bedtime preferences a fair opportunity to be explained.',[
'Prepare a balanced opening question that asks participants to describe their usual routine without implying that one choice is healthier. Use the same neutral prompts about reasons, practical constraints and exceptions after each account, whether or not the interviewer agrees with it.',
'Pilot the revised prompts with a consenting adult and ask whether any wording suggests the preferred answer. Train the interviewer to pause, avoid approval cues and ask for clarification rather than challenge a preference. Keep the interview about ordinary routines instead of diagnoses or distressing experiences.',
'With permission, record the interviews and retain a reflexive log of departures from the prompts. A second researcher can check a sample for uneven probing. Preserve withdrawal and confidentiality arrangements, and report remaining limitations. The design improves procedural fairness while retaining space for participants to introduce meanings the interviewer did not anticipate.'])))

CASES.append(dict(title='What counts as helping?',context='human-development',concept='measurement',codes=['RES.05','RES.05','RES.07','RES.08'],
case='A fictitious human-development practical observes how consenting students aged 17–18 support one another while learning an unfamiliar construction task. Two non-participant observers sit openly beside the work area. Their first coding sheet contains only “helpful” and “not helpful”. One observer counts pointing to a piece as helping, while the other counts only spoken explanations. No names or video are retained, and the task is ungraded.',
nodes=['Broad coding sheet','Consenting learners','Two overt observers','Helping-behaviour records'],
k=('Explain why operational definitions are needed for the behaviour recorded in this practical.',[
'An operational definition specifies the observable events that count as an instance of the target behaviour. The everyday term “helpful” is not enough because the two observers apply different rules to the same pointing action. Their records could therefore differ even when the learners behave identically.',
'A clearer definition might count a spoken explanation that names a construction step and is directed to a partner, while recording pointing in a separate category. The definition must be chosen to match the aim rather than merely to make counting convenient. It creates a consistent measure of selected helping behaviours, not a complete measure of a person’s helpfulness.']),
a=('Using measurement, explain a strength and a limitation of replacing “helpful” with precisely defined observable categories.',[
'Precise categories let both observers look for the same events. Separating explanations from pointing would make the recorded behaviour less dependent on an observer’s private interpretation of helpfulness. This improves consistency and makes the link between the research aim and the coding decision open to examination.',
'A narrow category can also leave out meaningful support. A quiet gesture might enable a partner to solve the task even though it contains no spoken explanation. The researcher should therefore justify the categories, pilot them against the activity and avoid treating the count as an exhaustive measure of social development. More precise measurement is not automatically more complete measurement.']),
c=('Compare and contrast this structured observation with an unstructured observation of the same construction activity.',[
'Both methods involve observing behaviour as it occurs during the construction task, rather than asking learners later to reconstruct every action. Either can be overt and non-participant, so the distinction concerns how observations are recorded rather than whether the researcher is physically present.',
'A structured sheet directs attention to predefined events and supports consistency across observers and sessions. It can miss unexpected forms of support. An unstructured record permits richer notes about an unforeseen gesture or interaction, but the choice of what is noteworthy depends more heavily on the observer and can be difficult to compare across groups.',
'The appropriate approach follows the aim. A preliminary unstructured observation could help develop sensible categories for later structured work. That sequence uses the exploratory value of one and the focused measurement of the other without assuming either can capture every feature of the interaction.']),
d=('Design a coding procedure that makes the records more consistent without treating all helping as a single behaviour.',[
'Develop separate, observable categories for spoken explanations, direct answers and non-verbal guidance. Define the start and end of an event and how to handle an action that fits more than one category. Include an “unclear” field rather than forcing every observation into an arbitrary judgement.',
'Pilot the sheet on a consenting group completing the same neutral task. The two observers should code independently, compare where their rules produced different decisions and revise the definitions before the main practical. Training should use examples and counterexamples so agreement does not depend on discussing each event while it happens.',
'During the practical, retain independent records and the same observation period for each group. Explain the overt observation and withdrawal arrangements beforehand. Report what the categories include and omit; consistent coding supports a defined measure but does not establish that the activity represents social development in every everyday setting.'])))

CASES.append(dict(title='Agreement without a complete measure',context='human-development',concept='perspective',codes=['RES.05','RES.06','RES.07','RES.08'],
case='In a fictitious practical, two observers independently record turn-taking in a supervised problem-solving club for consenting participants aged 16–18. They use a clear rule: count a turn only when a participant speaks for at least two seconds. The observers usually identify the same events. A club member notes that some participants contribute by arranging materials or using short gestures. The observers do not join in the activity.',
nodes=['Speech-duration rule','Two independent coders','Overt club observation','Recorded spoken turns'],
k=('Distinguish inter-observer reliability from validity with reference to this procedure.',[
'Inter-observer reliability concerns consistency between observers applying the coding rules. Their tendency to identify the same speaking events suggests that the two-second rule can be used consistently. This concerns agreement about what was recorded, not whether the rule captures the entire construct of participation.',
'Validity concerns whether the operational measure supports the intended interpretation. If the aim is broad participation, excluding material arrangement and short gestures may omit important contributions. A measure can therefore be reliable yet incomplete for that aim. It would be more defensible to describe the outcome narrowly as extended spoken turns than as all forms of participation.']),
a=('Using perspective, explain the value and limitation of consulting club members about the coding rule.',[
'Club members may notice forms of contribution that outside observers overlook because they understand the activity’s local meanings. Their perspective could show why a brief gesture or arranging a component is consequential even though it does not meet the speech-duration rule. Consulting them can therefore challenge an unnecessarily narrow interpretation.',
'Their views should inform, not automatically determine, the measure. Members may disagree about which actions count, and one confident member may not speak for quieter participants. The researcher can seek varied accounts and revise categories transparently while retaining independent observation. The resulting interpretation becomes better informed by participant perspectives rather than being guaranteed correct.']),
c=('Compare and contrast participant and non-participant observation for investigating contributions in this club.',[
'Both can be used to observe contributions during the actual club activity, and both require careful decisions about consent and recording. Being a participant observer concerns joining the activity; it is distinct from whether participants know that observation is taking place.',
'A participant observer may understand why a particular gesture advances the shared task and may build rapport. Joining in also changes the group’s interaction and divides attention between participating and recording. A non-participant observer can concentrate on the agreed coding procedure but may misinterpret an action when its local meaning is not apparent.',
'Neither position provides a view without influence. A defensible design states the researcher’s role and evaluates its consequences for this aim. Brief participant consultation could supplement non-participant coding without pretending that the observer has become an insider or that the data are free of perspective.']),
d=('Design a revision that retains independent coding but improves the coverage of contributions.',[
'Begin by clarifying whether the aim concerns extended speech or broader participation. For the broader aim, consult consenting members with varied levels of verbal participation and observe a pilot session to identify distinct non-verbal contributions. Develop categories with concrete behavioural examples rather than an overall label such as “engaged”.',
'Train both observers on the revised sheet, then have them code the same pilot independently. Discuss ambiguous boundaries and refine the rules before using the sheet in the main practical. Keep an explicit rule for simultaneous speech and gestures so an apparent improvement is not merely a change in double-counting.',
'Preserve the non-participant role, equal observation periods and secure, de-identified records. Report which contributions remain outside the categories and whether the revisions changed what is being measured. The design seeks both consistency and broader construct coverage; these are related goals that need separate justification.'])))

CASES.append(dict(title='Visible observers in a familiar setting',context='human-development',concept='change',codes=['RES.03','RES.03','RES.07','RES.08'],
case='A fictitious observation practical examines how consenting older adolescents use explanations during a familiar collaborative puzzle session. An observer, introduced to everyone in advance, sits at the edge of the room and does not participate. Several participants become unusually formal while the observer is present. The class considers moving the activity to a research room, but also wants to understand interaction in the familiar club setting.',
nodes=['Advance consent','Visible observer','Familiar puzzle session','Interaction records'],
k=('Explain what makes this an overt, non-participant observation.',[
'The observation is overt because the participants know that their behaviour is being observed for the practical. Advance introduction and consent make the research role visible rather than concealed. Overt does not mean that the participants necessarily understand every later interpretation of their behaviour.',
'It is non-participant because the observer does not join in solving the puzzle or act as a member of the group. This can allow attention to recording, but physical non-participation does not mean no influence: participants may still alter their explanations because they know the observer is watching. The two labels describe different features of the procedure.']),
a=('Using change, explain how the observer’s presence could affect the behaviour that the practical aims to investigate.',[
'The act of measurement can change the interaction being measured. Participants who normally use abbreviated explanations may become formal to present themselves as cooperative or articulate. The observation would then describe behaviour under visible observation, rather than simply recording the familiar pattern unchanged.',
'The researcher should avoid treating this difference as evidence that participants have developed a lasting new communication style. It may be a temporary response to the research situation. Several consenting familiarisation visits and a restrained observer role could reduce novelty, while an honest account of remaining reactivity keeps the conclusion tied to the conditions actually observed.']),
c=('Compare and contrast observing the familiar club with observing the same task in a controlled research room.',[
'Both settings can use the same puzzle, behavioural definitions and non-participant role. The researcher can therefore retain some consistency in what is observed while changing the setting. Neither observation alone establishes that the setting causes a lasting developmental difference.',
'The familiar club preserves the usual social environment and may reveal behaviour embedded in established relationships. Noise, interruptions and other activities can vary between sessions. A research room permits more consistent arrangements, but moving the group may change expectations and remove contextual features that make the club interaction meaningful.',
'The comparison is a trade-off between control and resemblance to the setting of interest, not a rule that one setting is always superior. If the aim is everyday club interaction, contextual detail is a strength worth preserving. If the aim requires tightly comparable observation conditions, controlled sessions may be justified with appropriately narrower claims.']),
d=('Design an ethically acceptable way to reduce the novelty of observation without secretly recording participants.',[
'Retain explicit informed consent and explain the observer’s role, what will be recorded and when data will be deleted. Arrange brief familiarisation visits during ordinary, low-stakes puzzle activities before collecting the main observations. Participants must still be able to decline or withdraw without losing access to the club.',
'Use the same unobtrusive seating position and a pre-agreed non-participant role across sessions. Do not introduce hidden cameras or conceal the purpose in order to obtain supposedly natural behaviour. A short pilot can check whether the observer can record the agreed categories without joining the task or interrupting participants.',
'Document contextual changes across visits and acknowledge that familiarity does not prove the disappearance of reactivity. The resulting account can be compared across observation occasions while remaining limited to consensually observed behaviour. This addresses novelty without sacrificing the responsibility to respect participants’ knowledge and control.'])))

CASES.append(dict(title='Sampling across two club schedules',context='human-relationships',concept='measurement',codes=['RES.02','RES.05','RES.07','RES.08'],
case='A fictitious class survey asks adult members of a community club about preferred ways of organising shared activities. With permission, a researcher obtains a current membership list divided into daytime and evening members. They randomly select invitations within each group. Selected members receive the same short questionnaire, but several say that the phrase “regular contact” is unclear. Participation is voluntary, and membership administrators cannot see individual answers.',
nodes=['Complete membership list','Daytime and evening groups','Random invitations within groups','Same voluntary questionnaire'],
k=('Explain how this procedure uses stratified random sampling.',[
'The researcher first divides the defined membership population into relevant subgroups, or strata, based on session schedule. Invitations are then selected by chance within each subgroup. This provides a planned way to include both daytime and evening members rather than relying on who happens to attend when recruitment occurs.',
'The random element must operate within each group; simply inviting a convenient number from each schedule would instead be a quota-style procedure. The intended numbers and selection rule should be stated. Stratification concerns selection into the sample, not assigning a person to a treatment, and subsequent refusal can still affect the final coverage.']),
a=('Using measurement, explain why identical questionnaire wording may still produce non-equivalent accounts of contact preferences.',[
'Identical words do not guarantee identical interpretations. One member may use “regular contact” to mean a daily message while another may mean a monthly meeting. Their answers could reflect different meanings of the question rather than different preferences for the same amount or kind of contact.',
'The researcher should pilot the item with people from both schedules and ask them to explain their interpretation. Replacing the vague phrase with a defined period and a specified communication form would make the comparison more interpretable. Such a revision should still be checked for whether it captures the relationship-organising behaviour of interest rather than only what is easy to count.']),
c=('Compare and contrast this stratified random approach with simple random sampling from the full club list.',[
'Both use a defined membership list and chance-based selection rather than approaching only convenient attendees. Both still require informed consent, and both may be affected by a selected member declining the questionnaire. Neither sampling procedure makes a poorly worded item valid.',
'Simple random sampling selects directly from the full list, without first ensuring invitations to each schedule group. In a small sample, one schedule might receive few invitations by chance. Stratification deliberately structures selection across the two groups, which is useful when the research aim requires both schedules to be heard.',
'Stratification requires reliable group information and a justified allocation rule. Simple random sampling is easier when only the full list is available. The advantage therefore depends on whether schedule is relevant to the aim; adding strata mechanically does not guarantee that the final consenting sample represents every important difference between members.']),
d=('Design a pilot procedure that checks the meaning of the contact-preference items before the main survey.',[
'Invite a small, voluntary group of adults from both club schedules who will not be included in the main survey. Ask them to complete the proposed questionnaire privately, then explain how they understood “regular contact” and what time period they considered. Make clear that the item, rather than the participant’s comprehension, is being checked.',
'Compare the interpretations qualitatively to identify ambiguity, without treating the pilot as a population estimate. Rewrite the item to specify a time window and communication form, and provide response options that do not assume every member uses the same service. Check the revised wording with further consenting readers.',
'Keep pilot comments separate from the main survey, remove identifying details and explain the agreed deletion point. Record what changed and why so that the final measurement decision is transparent. The pilot improves the operational meaning of the questions but cannot prove that all future respondents will interpret them identically.'])))

CASES.append(dict(title='The impossible withdrawal promise',context='human-relationships',concept='responsibility',codes=['RES.04','RES.04','RES.07','RES.08'],
case='A fictitious anonymous survey asks consenting adult learners which forms of peer feedback they prefer. The form collects no names, contact details, identifying codes or device identifiers. The consent page nevertheless promises that an individual can have their particular answers removed up to one month later. Once submitted, the researcher cannot identify which response belongs to whom. The class wants to preserve privacy while making a realistic withdrawal statement.',
nodes=['Consent information','No identifying information collected','Anonymous submission','Individual answers cannot be traced'],
k=('Distinguish anonymity from confidentiality with reference to this survey.',[
'Anonymity means that an individual response cannot be linked back to an identified participant through the retained information. The stipulated form collects no name or identifying code, so the researcher has no practical route to locate a particular person’s submission later. This is why the withdrawal promise creates a problem.',
'Confidentiality instead concerns protecting information that may still be linked to an individual, for example a securely stored interview recording with a name removed only at a later stage. Confidential data are not automatically anonymous. The survey’s privacy strength does not make it possible to remove a particular anonymous response after it can no longer be identified.']),
a=('Using responsibility, explain how the consent information should address withdrawal honestly.',[
'Researchers should give participants accurate information about the choices that remain available. Promising later removal when a submitted response cannot be traced gives a false impression of control and prevents fully informed consent. A participant may decide differently if they know the practical limit in advance.',
'For a genuinely anonymous form, the researcher could explain that participants may stop before submitting and leave items unanswered, but that an individual response cannot be removed after anonymous submission. Alternatively, a temporary participant-held code could enable withdrawal until a clearly stated anonymisation date. The privacy and withdrawal consequences of either arrangement must be explained rather than hidden.']),
c=('Compare and contrast a fully anonymous survey with a temporarily coded confidential survey for this aim.',[
'Both can ask the same feedback-preference questions, permit voluntary participation and protect responses from membership or teaching staff. Both require secure handling and truthful consent information. Neither arrangement makes it acceptable to require completion or to pressure someone to disclose a preference.',
'A fully anonymous survey reduces the retained link to identity and may encourage candid answers, but prevents the researcher locating a particular submitted response. A temporary code allows a participant to request removal before the code link is deleted, at the cost of retaining a link that must be protected carefully.',
'The choice depends on the importance of later withdrawal and follow-up for the research aim. If no follow-up is needed, collecting additional identifiers simply out of habit would create avoidable exposure. If coding is justified, specify its purpose, access restrictions and deletion schedule, rather than presenting coded data as already anonymous.']),
d=('Design a consent and data-handling procedure for a genuinely anonymous version of this survey.',[
'Explain the aim and ordinary preference questions before participation. State that the form is voluntary, can be closed without submission and permits unanswered items. Clearly state that the researcher cannot remove an individual response after it has been submitted anonymously; do not promise later tracing.',
'Configure the form so it does not record identifying fields or device identifiers, as stipulated in this practice case. Avoid free-text prompts that invite names, named peers or recognisable incidents. Check the form settings before use and ensure that no teacher or club administrator receives individual submissions.',
'Store the resulting dataset in a restricted location and specify when it will be deleted. Publish only appropriately combined information and review small categories for indirect identifiability. The procedure protects privacy while acknowledging the genuine limit on post-submission withdrawal, rather than claiming that every desirable protection can be maximised simultaneously.'])))

CASES.append(dict(title='A changing setting and a repeated questionnaire',context='human-relationships',concept='change',codes=['RES.05','RES.03','RES.07','RES.08'],
case='A fictitious class questionnaire asks consenting adults about opportunities to talk with other members of a study club. The same volunteers complete the questionnaire twice. Between the two occasions, the club changes from individual work to scheduled group activities. The researcher proposes using differences between the two sets of responses as the sole indication of whether the questionnaire is reliable. No personal conflict or mental-health information is collected.',
nodes=['First questionnaire','Club activities change','Second questionnaire','Reliability claim proposed'],
k=('Explain the purpose of test–retest reliability and why this schedule complicates its interpretation.',[
'Test–retest reliability concerns the consistency of a measure across occasions when the underlying characteristic is sufficiently stable. Repeating the same questionnaire can help examine temporal consistency, but only if a changed response is not readily explained by a real change in what is being measured.',
'Here the opportunity to talk may genuinely change when group activities are introduced. Different answers could therefore reflect changed experience rather than an unstable questionnaire. Conversely, identical answers would not prove that the items measure the intended construct. The researcher must distinguish consistency from validity and consider the intervening circumstances.']),
a=('Using change, explain why the researcher should consider more than one explanation for different questionnaire responses.',[
'A difference across occasions may arise from genuine changes in club opportunities, shifts in how participants understand an item, or inconsistency in responding. The new group activities provide a concrete reason to expect that the underlying experience could have changed. Attributing every difference to measurement failure would ignore this alternative.',
'The researcher should document what changed between occasions and clarify whether the aim is to examine the questionnaire or the changed club experience. A design cannot isolate a measurement problem merely by repeating an instrument in a changing environment. A proportionate conclusion recognises both the possible change in experience and the remaining uncertainty about the measure.']),
c=('Compare and contrast closed response options with open-ended items for this questionnaire.',[
'Both ask participants to report their own experience of opportunities to interact, so both can be affected by memory, interpretation and willingness to disclose. Either can be administered privately at both occasions with voluntary consent; response format alone does not establish truthful reporting.',
'Closed options provide consistent categories and reduce the burden of answering, but may force varied experiences into an unsuitable choice. An open-ended item permits a participant to explain that scheduled groups increased some conversations while reducing others. Such detail takes longer to produce and interpret and may vary greatly in length.',
'The formats can complement one another if each serves the aim. A clearly defined closed item can establish a common reference period, while a neutral optional comment can reveal unanticipated meanings. The researcher should not assume that more text is automatically better evidence, or that standardised options remove the need to examine validity.']),
d=('Design a more defensible procedure for examining the questionnaire’s temporal consistency.',[
'Choose a period in which the club arrangements are expected to remain reasonably stable, and explain why the experience being measured should not change substantially in that interval. Use the same reference period and administration conditions on both occasions, without telling participants that they are expected to repeat their first answers.',
'Ask a neutral contextual question about important changes since the first occasion, so that genuine changes can be considered rather than automatically classified as unreliability. Use a secure participant-held code if matching responses is needed, and explain the distinction between temporary confidentiality and later anonymisation.',
'Pilot the item wording for clarity and record the final timing and procedure. Acknowledge that a very short interval may permit recall of earlier answers, whereas a long interval permits genuine change. The purpose is a justified compromise suited to this measure, not a schedule that guarantees a desired appearance of reliability.'])))

CASES.append(dict(title='Random allocation and two changes at once',context='learning-cognition',concept='causality',codes=['RES.03','RES.03','RES.07','RES.08'],
case='In a fictitious low-stakes classroom experiment, consenting adults are recruited through a volunteer notice. A chance procedure allocates them to two groups learning the same unfamiliar factual passage for the same time. One group sees a small-font, densely spaced version; the other sees a larger-font, widely spaced version. Both complete the same recall task. The stated aim is to investigate the effect of line spacing alone. The task is ungraded and participants may stop.',
nodes=['Consenting volunteers','Chance allocation','Small+dense or large+wide text','Identical recall task'],
k=('Distinguish random allocation from random sampling with reference to this experiment.',[
'Random allocation assigns participants who have already joined a study to its conditions by a chance procedure. Here it concerns whether a consenting volunteer receives the small, densely spaced passage or the large, widely spaced passage. It can reduce systematic participant differences between the conditions, although chance imbalances remain possible in a small sample.',
'Random sampling concerns how people are selected from a defined population before participation. This sample was recruited through a volunteer notice, so chance allocation does not turn it into a random sample of all adults. Internal comparison between conditions and generalisation beyond volunteers therefore require separate consideration.']),
a=('Using causality, explain why random allocation does not isolate the effect of line spacing in this design.',[
'The two conditions differ in font size as well as line spacing. Even if chance allocation balances participant characteristics reasonably well, a difference in recall could be attributable to font size, line spacing or their combination. Random allocation addresses one source of alternative explanation, not every procedural confound.',
'To isolate spacing, hold font size and all other relevant presentation features constant while varying only spacing. Alternatively, a more complex design could vary each feature separately, but the researcher must state that different aim. The original design can compare two combined text formats; it cannot justify assigning the outcome specifically to spacing alone.']),
c=('Compare and contrast this independent-groups design with a repeated-measures design using two equivalent passages.',[
'Both can manipulate text presentation while using recall as an operational measure of learning. Both need consistent exposure time and equivalent instructions. The independent-groups design compares different people, whereas the repeated-measures design exposes the same participant to each condition.',
'Repeated measures reduces the influence of stable individual differences in memory because each participant contributes to both conditions. It introduces order and practice effects, and the passages may not be perfectly equivalent. Independent groups avoids direct carry-over between passages but may have uneven baseline memory ability, especially with few volunteers.',
'Counterbalancing passage and condition order can help a repeated-measures design, while random allocation and an adequate sample help independent groups. Neither choice solves the original two-feature confound. A defensible comparison therefore separates participant design from the need to isolate the intended independent variable.']),
d=('Design a feasible independent-groups version that better isolates line spacing.',[
'Prepare two versions of one unfamiliar passage with identical wording, font size, colour and page size; alter only line spacing. Pilot readability so that either version remains a reasonable, non-distressing task. Define the recall measure in advance, for example the number of accurately reproduced target ideas under one marking rule.',
'Recruit consenting adults through a neutral invitation and allocate them to the versions using a chance procedure. Standardise study time, instructions, environment and the delay before the same recall task. A scorer who does not know the participant’s condition can apply the agreed rule to de-identified answers.',
'Keep the task ungraded and make withdrawal possible without a penalty. Record departures from the procedure and describe the volunteer-sample boundary when reporting the findings. This revision improves the spacing comparison while leaving the need to consider chance, measurement quality and wider generalisation.'])))

CASES.append(dict(title='Practice that carries into the next condition',context='learning-cognition',concept='measurement',codes=['RES.03','RES.05','RES.07','RES.08'],
case='A fictitious class practical compares two harmless ways to learn unfamiliar words. Every consenting participant studies one list using spoken rehearsal and another using imagery. Half receive rehearsal first and half receive imagery first. Equivalent lists are rotated across the two orders. The teacher warns that participants may continue using imagery when later instructed to rehearse, so experiencing one strategy could alter the next condition. No findings are supplied.',
nodes=['Same consenting participants','Two equivalent word lists','Two strategy orders','Possible strategy carry-over'],
k=('Explain counterbalancing and what it can address in this procedure.',[
'Counterbalancing varies the order of conditions across participants rather than giving everyone the same sequence. Here half receive rehearsal before imagery and half receive the reverse order, while lists are rotated. This reduces the risk that a simple first-versus-second position difference is always attached to one strategy.',
'It does not ensure that all order effects cancel. If learning imagery changes how someone later performs rehearsal, the carry-over may differ between sequences. Equivalent lists also require justification rather than merely being labelled equivalent. Counterbalancing is therefore a control for some order-related alternatives, not proof that the comparison is free of carry-over.']),
a=('Using measurement, explain why strategy carry-over could make the condition labels a poor account of what participants actually did.',[
'The intended measure concerns performance under two distinct learning strategies. If a participant continues forming images during the rehearsal condition, the label “rehearsal” no longer represents only the intended procedure. A score in that condition could reflect a mixture of strategies rather than the operation stated in the design.',
'A neutral strategy-use check can help identify the problem, but self-report after the task is not a perfect record of mental activity. The researcher should pilot instructions, consider whether strategies can realistically be separated and avoid treating nominal condition labels as proof of compliance. The issue concerns the validity of the manipulation as well as the precision of the recall score.']),
c=('Compare and contrast repeated measures with independent groups for investigating these learning strategies.',[
'Both designs can compare the same strategy instructions using a common recall measure and equivalent material. Both require voluntary consent, standardised procedures and attention to the validity of what participants actually do. They differ in whether each participant experiences one or both strategies.',
'Repeated measures controls stable participant differences efficiently because each person contributes to both conditions. Here that advantage is threatened by strategy transfer: learning imagery may change later rehearsal. Independent groups removes that direct sequence within a person, but different memory ability or previous strategy experience can create between-group differences.',
'Chance allocation and an appropriate sample improve the independent-groups comparison. Counterbalancing and pilot checks improve repeated measures, although they cannot guarantee the removal of asymmetric carry-over. The preferable design depends on whether the strategies can be kept sufficiently distinct, rather than on a rule that repeated measures is always more controlled.']),
d=('Design a revision that avoids exposing each participant to both strategies while retaining a fair comparison.',[
'Use independent groups: each consenting participant receives either the rehearsal or imagery instruction for an equivalent unfamiliar list. Allocate participants by chance and rotate the material across groups using a pre-agreed schedule so one list is not inseparable from one strategy.',
'Provide equal practice with the assigned instruction, identical study time and the same recall delay. Use a clear scoring rule and, if feasible, a scorer unaware of strategy assignment. Ask a brief neutral question after the task about strategy use to assess whether the instructions were followed, without classifying every unexpected response as dishonest.',
'Retain low-stakes, ungraded participation and withdrawal arrangements. Report that the revision avoids within-person sequence transfer but introduces a need to consider between-person variation. This is a justified trade-off, not a guarantee that any observed difference can only be caused by the intended strategy.'])))

CASES.append(dict(title='Confidence is not delayed recall',context='learning-cognition',concept='causality',codes=['RES.05','RES.05','RES.07','RES.08'],
case='In a fictitious experiment, consenting adults are randomly allocated to re-reading a short passage or trying to recall it from memory. Immediately afterwards, they rate how well they think they will remember it tomorrow. The researcher calls this rating a measure of next-day recall, although no next-day memory task is administered. All learning is low-stakes and ungraded, and volunteers can withdraw.',
nodes=['Chance allocation','Re-reading or retrieval','Immediate confidence rating','Next-day recall not tested'],
k=('Explain why an operational definition must distinguish predicted memory from observed memory performance.',[
'An operational definition states how a construct is measured in the procedure. The rating measures a participant’s current judgement of expected future memory. It does not observe how much information that participant can actually recall after a day, because the stipulated procedure contains no delayed memory task.',
'Confidence and performance may be related, but the relationship cannot simply be assumed. A participant can feel fluent while re-reading without later reproducing the information accurately. The researcher should name the rating as a prediction or confidence measure and use an appropriate delayed task if the aim concerns next-day recall.']),
a=('Using causality, explain the strongest kind of conclusion the random allocation could support and the conclusion it cannot support here.',[
'Provided the conditions are implemented consistently, chance allocation strengthens an inference about the effect of the assigned learning procedure on the measured confidence rating. It helps reduce systematic pre-existing differences between groups, although chance and procedural alternatives still require consideration.',
'It cannot by itself establish an effect on next-day recall, which was never measured. A strong causal design does not repair a mismatch between the outcome and the claim. The researcher must therefore keep a conclusion about confidence distinct from a conclusion about retained knowledge, rather than extending the result to an unobserved outcome.']),
c=('Compare and contrast this true experiment with comparing adults who independently choose re-reading or retrieval practice.',[
'Both approaches could collect confidence ratings after a learning activity, and both require a clear definition of the activity and outcome. The true experiment assigns the activity through a chance procedure. A comparison based on participants’ independent choices does not provide that allocation.',
'People choosing retrieval may differ in previous study experience, motivation or beliefs about memory. Those differences can help explain their confidence, so the self-selected comparison provides weaker grounds for isolating an effect of the learning activity. The true experiment better separates assignment from those preferences, while its imposed procedure may be less like ordinary independent studying.',
'Neither comparison measures next-day recall unless a delayed task is added. The appropriate conclusion therefore depends both on allocation and on the outcome actually recorded. Calling a study experimental is not sufficient justification for a broader claim about learning effectiveness.']),
d=('Design an ethical addition that measures delayed recall rather than merely predicting it.',[
'Retain the randomly allocated learning activities but add the same low-stakes recall task after a specified delay, such as the next day. Define the target ideas and scoring rule in advance, and pilot the task to ensure it measures the supplied material rather than unrelated specialist knowledge.',
'Give both groups the same instructions about access to the passage during the interval, record any unplanned additional study and administer the recall task under comparable conditions. Keep the original confidence rating as a separate measure if it serves a stated aim; do not combine the two outcomes into one undefined score.',
'Explain the follow-up commitment and voluntary withdrawal before consent. Use secure codes only as needed to match occasions, and remove the link at the agreed point. The addition makes delayed performance observable while leaving realistic limitations such as extra study, absence at follow-up and the restricted volunteer sample.'])))

from methods_evaluation import EVALS

def build():
    questions=[];records=[]
    names=['p2-a-knowledge','p2-a-application','p2-a-comparison','p2-a-design']
    for index,c in enumerate(CASES):
        for j,key in enumerate(['k','a','c','d']):
            prompt,steps=c[key]; number=index*4+j+1
            code=c.get('codes',['RES.01','RES.05','RES.07','RES.08'])[j]
            illustration=flow(c['title'],c['nodes']) if key in ['a','d'] else None
            stem='**Constructed class-practical case.** '+c['case']+'\n\n'+prompt+'\n\nThis self-contained item practises Paper 2A methodology. In an examination requiring your own class practical, use the practical you actually studied.'
            q=question('res',number,c['title']+' — '+['Method knowledge','Concept application','Method comparison','Research design'][j],code,names[j],stem,steps,difficulty=('medium' if j<2 else 'hard'),context=c['context'],concepts=[c['concept']],diagram=illustration,caption='Original schematic of the fictitious practical; arrows show procedural order, not causal effects.')
            questions.append(q)
            records.append(evidence(q,'The specific method demand is: '+prompt+' The worked reasoning follows the supplied recruitment, procedure and participant relationship. It distinguishes improving a method from proving that bias or uncertainty has disappeared. '+steps[-1],sources=[GUIDE],figure={'type':'procedural flow','nodes':c['nodes'],'meaning':'Arrows order the fictional procedure; they assert no psychological cause, numerical finding or treatment effect.'} if illustration else None,alternatives=['Credit another feasible, ethical methodological choice when it is justified against the stated aim and constraints.']))
    for index,c in enumerate(EVALS):
        number=49+index
        prompt='Discuss this study with reference to at least two of the following concepts: '+', '.join(c['concepts'])+'.'
        q=question('res',number,c['title'],'RES.'+c.get('code','03'),'p2-b','**Unseen research study: entirely constructed for practice.** '+c['case']+'\n\n'+prompt,c['steps'],difficulty='hard',context=c['context'],concepts=c['concepts'],diagram=flow(c['title'],c['nodes']) if c.get('nodes') else None,caption='Original design schematic for the simulated study; arrows show recruitment or procedure, not evidence of causation.')
        questions.append(q)
        records.append(evidence(q,'The evaluation is bounded by the explicitly simulated design rather than invented published findings. '+prompt+' The answer develops competing interpretations of the specific recruitment, measurement and causal claims, and ends with a proportionate conclusion. '+c['steps'][-1],sources=[GUIDE],figure={'type':'procedural flow','nodes':c.get('nodes'),'meaning':'Procedure only; no numerical result, clinical recommendation or unsupported causal arrow.'} if c.get('nodes') else None,alternatives=['Other combinations of two or more of the four specified concepts can receive full credit if developed using this study and a justified judgement.']))
    return questions,records

if __name__=='__main__':
    questions,records=build()
    assert len(questions)==60, 'Complete all twelve practical cases and twelve unseen-study evaluations before release.'
    binding=write_collection('res',questions)
    for record in records:record['author']='root' if int(record['questionId'].rsplit('-',1)[1])<=48 else 'mock_portal_audit'
    dump(DOCS/'methods-author.json',{'status':'author-checks-passed; independent review required','reviewer':'root methodology author with mock_portal_audit authoring the twelve unseen-study evaluations','authors':['root','mock_portal_audit'],'questions':len(questions),'files':[binding],'records':records,'openFindings':[]})
